/* Local Functions */

static uint8_t bcd2bin(uint8_t v)
{
  return (v & 0x0F) + ((v >> 4) * 10);
}

static uint8_t bin2bcd(uint8_t v)
{
  return (uint8_t)(((v / 10) << 4) | (v % 10));
}

/* Send CAN Message */
void CAN_SendMessage(uint32_t ID, uint8_t DLC, uint8_t * Data)
{
	/* Header */
	txHeader.StdId = ID;          		// ID standard (11 bit)
	txHeader.ExtId = 0;              	// Non usato se IDE = STD
	txHeader.IDE   = CAN_ID_STD;     	// CAN_ID_STD oppure CAN_ID_EXT
	txHeader.RTR   = CAN_RTR_DATA;   	// CAN_RTR_DATA o CAN_RTR_REMOTE
	txHeader.DLC   = DLC;              	// Numero byte (0..8)
	txHeader.TransmitGlobalTime = DISABLE;

	/* Data */
	txData[0] = Data[0];
	txData[1] = Data[1];
	txData[2] = Data[2];
	txData[3] = Data[3];
	txData[4] = Data[4];
	txData[5] = Data[5];
	txData[6] = Data[6];
	txData[7] = Data[7];

	/* Wait for the mailbox to become free */
	while (HAL_CAN_GetTxMailboxesFreeLevel(&hcan) == 0)
	{
		Os_Yield();
	}

	/* Transmit message */
	if (HAL_CAN_AddTxMessage(&hcan, &txHeader, txData, &txMailbox) != HAL_OK)
	{
	    /* Tx Error */
	}
}

