/* RTC read */
HAL_StatusTypeDef DS3231_ReadDateTime(I2C_HandleTypeDef *hi2c, DS3231_DateTime *dt)
{
  uint8_t raw[8];

  // Read 7 byte: sec, min, hour, dow, date, month, year - Bug on I2C HAL, last byte duplicated.
  HAL_StatusTypeDef st = HAL_I2C_Mem_Read(
      hi2c,
      DS3231_ADDR,
      DS3231_REG_TIME,
      I2C_MEMADD_SIZE_8BIT,
      raw,
      8,
      100
  );

  if (st != HAL_OK) return st;

  // Seconds: bit7 = CH (clock halt)
  dt->seconds = bcd2bin(raw[0] & 0x7F);
  dt->minutes = bcd2bin(raw[1] & 0x7F);

  // Hours
  if (raw[2] & 0x40) {
    // 12-hour mode
    uint8_t hour12 = bcd2bin(raw[2] & 0x1F);
    uint8_t pm = (raw[2] & 0x20) ? 1 : 0;
    // 24h format conversion
    if (hour12 == 12) dt->hours = pm ? 12 : 0;
    else dt->hours = pm ? (hour12 + 12) : hour12;
  } else {
    // 24-hour mode
    dt->hours = bcd2bin(raw[2] & 0x3F);
  }

  dt->dayOfWeek = bcd2bin(raw[3] & 0x07);
  dt->day       = bcd2bin(raw[4] & 0x3F);

  // Month: bit7 = Century
  dt->month = bcd2bin(raw[5] & 0x1F);

  // Year: 0..99 => assumption 2000+ (tipical on DS3231)
  dt->year = 2000 + bcd2bin(raw[6]);

  return HAL_OK;
}

/* RTC Set */
HAL_StatusTypeDef DS3231_SetDateTime(I2C_HandleTypeDef *hi2c, const DS3231_DateTime *dt)
{
  uint8_t raw[7];

  // seconds
  raw[0] = bin2bcd(dt->seconds) & 0x7F;
  raw[1] = bin2bcd(dt->minutes) & 0x7F;

  // hours in 24h mode
  raw[2] = bin2bcd(dt->hours) & 0x3F;

  raw[3] = bin2bcd(dt->dayOfWeek) & 0x07;
  raw[4] = bin2bcd(dt->day) & 0x3F;

  // month: bit7 = century (0 => 2000..2099)
  raw[5] = bin2bcd(dt->month) & 0x1F;

  // year: DS3231 memorize 0..99
  uint8_t yy = (dt->year >= 2000) ? (uint8_t)(dt->year - 2000) : (uint8_t)(dt->year % 100);
  raw[6] = bin2bcd(yy);

  // Burst write 7 byte starting from 0x00
  return HAL_I2C_Mem_Write(
      hi2c,
      DS3231_ADDR,
      0x00,
      I2C_MEMADD_SIZE_8BIT,
      raw,
      7,
      100
  );
}

HAL_StatusTypeDef DS3231_DumpDecoded(I2C_HandleTypeDef *hi2c)
{
  uint8_t raw[7] = {1,2,3,4,5,6,7};

  HAL_StatusTypeDef st = HAL_I2C_Mem_Read(
      hi2c, DS3231_ADDR, 0x00, I2C_MEMADD_SIZE_8BIT, raw, 7, 100);

  st = HAL_I2C_Mem_Read(
      hi2c, DS3231_ADDR, 6, I2C_MEMADD_SIZE_8BIT, &raw[6], 1, 100);

  if (st != HAL_OK) return st;
  printf("DS3231 RAW: %02X %02X %02X %02X %02X %02X %02X\r\n",
         raw[0], raw[1], raw[2], raw[3], raw[4], raw[5], raw[6]);

  uint8_t sec  = bcd2bin(raw[0] & 0x7F);
  uint8_t min  = bcd2bin(raw[1] & 0x7F);
  uint8_t hour = bcd2bin(raw[2] & 0x3F);
  uint8_t dow  = bcd2bin(raw[3] & 0x07);
  uint8_t dom  = bcd2bin(raw[4] & 0x3F);
  uint8_t mon  = bcd2bin(raw[5] & 0x1F);
  uint8_t yy   = bcd2bin(raw[6]);           // THIS is the year 00..99
  uint16_t year = 2000 + yy;

  printf("Decoded: %04u-%02u-%02u DOW=%u %02u:%02u:%02u\r\n",
         year, mon, dom, dow, hour, min, sec);

  return HAL_OK;
}

static void OLED_ShowTime(void *oled, const DS3231_DateTime *dt)
{
  char line1[16];
  char line2[22];

  // Set date and time
  snprintf(line1, sizeof(line2), "%04u-%02u-%02u", dt->year, dt->month, dt->day);
  snprintf(line2, sizeof(line1), "%02u:%02u:%02u", dt->hours, dt->minutes, dt->seconds);

  // Oled Write
  ssd1306_set_cursor(oled, 0, 30);
  ssd1306_write_string(oled, line1, 2);
  ssd1306_set_cursor(oled, 0, 40);
  ssd1306_write_string(oled, line2, 1);
  ssd1306_update(oled);
}

// Displays temperature on SSD1306 OLED.
void OLED_ShowTemperature(void *oled, float temperature_c)
{
  char line1[20];
  char line2[20];

  // Format strings
  snprintf(line1, sizeof(line1), "TEMPERATURE: %d C", (uint16_t)temperature_c);

  // Write temperature
  ssd1306_set_cursor(oled, 0, 50);
  ssd1306_write_string(oled, line1, 1);

  // Push buffer to display
  ssd1306_update(oled);
}
static uint16_t u16_le(const uint8_t *p) { return (uint16_t)(p[0] | (p[1] << 8)); }
static int16_t  s16_le(const uint8_t *p) { return (int16_t)u16_le(p); }

static HAL_StatusTypeDef bme_read(BME280_Handle *b, uint8_t reg, uint8_t *buf, uint16_t len)
{
  return HAL_I2C_Mem_Read(b->hi2c, b->addr, reg, I2C_MEMADD_SIZE_8BIT, buf, len, 200);
}

